import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static <T extends Comparable<T>> T findMax(List<T> list) {
        T max = list.get(0);
        for (T item : list) if (item.compareTo(max) > 0) max = item;
        return max;
    }
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        List<Integer> list = new ArrayList<>();
        for (String p : input.split(",")) list.add(Integer.parseInt(p.trim()));
        System.out.println(findMax(list));
    }
}

